css:
.question-bank {
  min-height: 100vh;
  background: linear-gradient(180deg, #f8f9fc 0%, #f1f3f8 100%);
  font-family: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
}
.qb-main {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px 32px 40px;
}
/* 上层 */
.qb-top {
  margin-bottom: 24px;
}
.qb-actions {
  position: relative;
  margin-bottom: 12px;
}
.action-scroll {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 4px 0;
}
.action-scroll::-webkit-scrollbar {
  display: none;
}
.action-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border: none;
  border-radius: 14px;
  background: #ffffff;
  cursor: pointer;
  transition: all 0.3s;
  white-space: nowrap;
  box-shadow: 0 2px 10px rgba(26, 43, 95, 0.04);
}
.action-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(26, 43, 95, 0.1);
}
.action-btn.active {
  background: linear-gradient(135deg, #1a2b5f, #1e3470);
  box-shadow: 0 4px 18px rgba(26, 43, 95, 0.3);
}
.action-btn.active .action-name {
  color: #ffffff;
}
.action-icon {
  font-size: 20px;
}
.action-name {
  font-size: 15px;
  font-weight: 700;
  color: #1a2b5f;
}
.action-tag {
  font-size: 9px;
  padding: 1px 6px;
  border-radius: 6px;
  background: #c41e3a;
  color: #fff;
  font-weight: 700;
}
.qb-sub-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sub-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border: 1px solid #e8eaf0;
  border-radius: 10px;
  background: #ffffff;
  font-size: 13px;
  font-weight: 600;
  color: #1a2b5f;
  cursor: pointer;
  transition: all 0.3s;
}
.sub-btn:hover {
  border-color: #c41e3a;
}
.search-box {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  padding: 8px 16px;
  background: #ffffff;
  border-radius: 10px;
  border: 1px solid #e8eaf0;
  width: 240px;
}
.search-box input {
  border: none;
  outline: none;
  font-size: 13px;
  flex: 1;
  color: #1a2b5f;
}
/* 主体 */
.qb-body {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 24px;
}
.category-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 20px;
  background: #ffffff;
  border-radius: 12px;
  padding: 4px;
  box-shadow: 0 1px 8px rgba(26, 43, 95, 0.04);
}
.cat-tab {
  flex: 1;
  padding: 12px;
  border: none;
  background: transparent;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 700;
  color: #5a6488;
  cursor: pointer;
  transition: all 0.3s;
}
.cat-tab.active {
  background: #1a2b5f;
  color: #ffffff;
  box-shadow: 0 2px 10px rgba(26, 43, 95, 0.3);
}
.subcategory-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.subcard {
  background: #ffffff;
  border-radius: 14px;
  padding: 18px 16px;
  cursor: pointer;
  transition: all 0.3s;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 1px 8px rgba(26, 43, 95, 0.04);
}
.subcard:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 18px rgba(26, 43, 95, 0.1);
}
.subcard-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}
.subcard-info {
  flex: 1;
}
.subcard-name {
  font-size: 14px;
  font-weight: 700;
  color: #1a2b5f;
  display: block;
  margin-bottom: 4px;
}
.subcard-count {
  font-size: 11px;
  color: #8a8faa;
}
/* 右侧 */
.qb-right {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.right-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 18px;
  box-shadow: 0 2px 12px rgba(26, 43, 95, 0.04);
}
.right-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  color: #1a2b5f;
  margin-bottom: 14px;
}
.log-stats {
  display: flex;
  justify-content: space-around;
}
.log-item {
  text-align: center;
}
.log-value {
  display: block;
  font-size: 22px;
  font-weight: 900;
  color: #1a2b5f;
  font-family: "DIN Alternate", sans-serif;
}
.log-label {
  font-size: 11px;
  color: #8a8faa;
}
.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.tool-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 12px 4px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s;
  font-size: 11px;
  color: #5a6488;
  background: #f8f9fc;
}
.tool-item:hover {
  background: #f0f2f5;
  transform: scale(1.03);
}

