categoryList.value:
() => {
  return [
    { key: 'xc', name: '行测' },
    { key: 'sl', name: '申论' },
    { key: 'ga', name: '公专' },
    { key: 'custom', name: '自定义刷题' }
  ];
}

currentSubCategories.value:
() => {
  const cat = this.state.activeCategory;
  if (cat === 'custom') return [{ key: 'custom-all', name: '自定义选题', count: 0, emoji: '⚙️', bg: '#f8f9fc' }];
  const subDefs = this.getSubDefinitions(cat);
  const statsMap = cat === 'xc' ? this.state.xingceStats : cat === 'sl' ? this.state.shenlunStats : this.state.gongzhuanStats;
  return subDefs.map(function(def) {
    const realCount = statsMap[def.name] !== undefined ? statsMap[def.name] : 0;
    return {
      key: def.key, name: def.name, count: realCount,
      emoji: (SUBCARD_STYLES[def.name] || {}).emoji || '📝',
      bg: (SUBCARD_STYLES[def.name] || {}).bg || '#f8f9fc'
    };
  });
}
